import { useState } from 'react'
import { Icon, type IconName } from '@/design-system/Icon'
import { Card } from '@/components/ui'
import { db } from '@/db/db'
import { useI18n, type MessageKey, baseLocale } from '@/i18n'

/**
 * Cari bantuan (CARE-01/02, blueprint 05 §6).
 *
 * TemuDua lists *categories* and what to ask, never invented practitioners.
 * A real directory needs verified names, credentials, and a last-verified date;
 * until those exist, inventing entries would be worse than having none.
 */

interface Category {
  icon: IconName
  title: MessageKey
  when: MessageKey
  /** Example questions, kept beside the category they belong to rather than
   *  scattered through the dictionary — they only ever appear here. */
  ask: { id: string[]; en: string[] }
}

const CATEGORIES: Category[] = [
  {
    icon: 'checkin',
    title: 'help.psy',
    when: 'help.psy.when',
    ask: {
      id: ['Kamu biasa nangani apa aja?', 'Sesinya berapa lama dan berapa biayanya?', 'Bisa online atau harus datang?'],
      en: ['What do you usually work with?', 'How long is a session and what does it cost?', 'Can it be online, or must I come in?'],
    },
  },
  {
    icon: 'heart',
    title: 'help.couple',
    when: 'help.couple.when',
    ask: {
      id: ['Kalau cuma satu yang mau datang, gimana?', 'Pendekatannya kayak apa?', 'Biasanya butuh berapa sesi?'],
      en: ['What if only one of us wants to come?', 'What is your approach?', 'How many sessions does it usually take?'],
    },
  },
  {
    icon: 'money',
    title: 'help.money',
    when: 'help.money.when',
    ask: {
      id: ['Kamu dibayar dari mana — fee atau komisi produk?', 'Bisa bantu pasangan, bukan cuma individu?'],
      en: ['How are you paid — a fee, or commission on products?', 'Do you advise couples, not just individuals?'],
    },
  },
  {
    icon: 'health',
    title: 'help.doctor',
    when: 'help.doctor.when',
    ask: {
      id: ['Perlu pemeriksaan apa dulu?', 'Ada efek samping yang perlu aku tahu?', 'Kapan aku harus balik lagi?'],
      en: ['What should be checked first?', 'Are there side effects I should know about?', 'When should I come back?'],
    },
  },
  {
    icon: 'baby',
    title: 'help.pediatric',
    when: 'help.pediatric.when',
    ask: {
      id: ['Ini masih wajar nggak untuk usianya?', 'Apa tanda yang bikin aku harus segera balik?'],
      en: ['Is this within the usual range for this age?', 'What signs mean I should come back straight away?'],
    },
  },
  {
    icon: 'shield',
    title: 'help.legal',
    when: 'help.legal.when',
    ask: {
      id: ['Apa yang bisa aku siapin sekarang?', 'Layanannya gratis atau berbayar?'],
      en: ['What can I prepare now?', 'Is the service free, or paid?'],
    },
  },
]

export default function Help() {
  const { t, locale: uiLocale } = useI18n()
  // `dwi` is a display mode, not a language — formatters and data tables
  // take the real one.
  const locale = baseLocale(uiLocale)
  const [prepFor, setPrepFor] = useState<string | null>(null)

  /**
   * Quick exit: leaves the page immediately and replaces the history entry, so
   * Back does not return to this screen. Not a promise of safety, but it does
   * remove the obvious trace.
   */
  function quickExit() {
    // Close the in-memory Dexie handle so a re-opened tab starts cold.
    db.close()
    window.location.replace('https://www.google.com')
  }

  return (
    <div className="stack">
      <div className="row row--between">
        <h1>{t('help.title')}</h1>
        <button className="btn btn--danger btn--sm" onClick={quickExit}>
          <Icon name="close" size={16} /> {t('help.quickExit')}
        </button>
      </div>

      <p className="banner banner--danger">
        <Icon name="emergency" size={18} />
        <span>{t('help.emergency')}</span>
      </p>

      <p className="card__hint">{t('help.intro')}</p>

      {CATEGORIES.map((c) => (
        <Card key={c.title} title={t(c.title)} icon={c.icon} hint={t(c.when)}>
          <button
            className="btn btn--ghost btn--sm"
            aria-expanded={prepFor === c.title}
            onClick={() => setPrepFor((p) => (p === c.title ? null : c.title))}
          >
            {prepFor === c.title ? t('common.close') : t('help.whatToAsk')}
          </button>
          {prepFor === c.title && (
            <ul className="list" style={{ marginTop: 'var(--space-2)' }}>
              {c.ask[locale].map((q) => (
                <li key={q} className="list__item">
                  <Icon name="info" size={16} />
                  <span className="grow">{q}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      ))}

      <p className="disclaimer">{t('help.safetyNote')}</p>
    </div>
  )
}
